   "body": "現實生活中成癮（addiction）隨處可見，如藥物、酒精等物質成癮；而時至今日「網路成癮」是一普遍存在的議題，網路成癮者對網路產生過度依賴現象，超時的網路使用（如網路遊戲），嚴重影響生活。試述壓力與成癮的關聯，及成癮之生理、心理歷程。（25 分）",
